"""Materialise the CMake project file for Golden Axe: The Revenge of Death Adder.

The repository intentionally carries no CMake file (owner request). This script writes CMakeLists.txt
in the repository root when a build starts; CMakeLists.txt is ignored by git and is not part of the
published source archive.
"""
from pathlib import Path

CONTENT = '# Golden Axe: The Revenge of Death Adder — native System 32 port\n#\n# The board model, video library and sound chips are shared with cheviman\'s System 32 decompilation\n# lineage (BSD-3-Clause; see LICENSE-arcade-decomp-BSD-3-Clause.txt). The game\'s V60 program is\n# translated to C by tools/recompile.py from the player\'s own ROM set at build time; no ROM and no\n# generated game code is part of this source tree.\ncmake_minimum_required(VERSION 3.20)\nproject(ga2 C CXX)\n\nset(CMAKE_C_STANDARD 11)\nset(CMAKE_C_STANDARD_REQUIRED ON)\nset(CMAKE_CXX_STANDARD 17)\nset(CMAKE_CXX_STANDARD_REQUIRED ON)\n\nset(GA2_BIN_DIR ${CMAKE_SOURCE_DIR}/build/bin CACHE PATH "Where the executables go")\nforeach(config IN ITEMS "" _DEBUG _RELEASE _RELWITHDEBINFO _MINSIZEREL)\n\tset(CMAKE_RUNTIME_OUTPUT_DIRECTORY${config} ${GA2_BIN_DIR})\nendforeach()\n\nif(MSVC)\n\tadd_compile_options(/W3 /utf-8)\n\tadd_compile_definitions(_CRT_SECURE_NO_WARNINGS)\nendif()\n\n# ---- System 32 board model -------------------------------------------------------------------------\nadd_library(s32runtime STATIC\n\truntime/src/machine.c\n\truntime/src/io.c\n\truntime/src/script.c\n\truntime/src/sound.c\n\truntime/src/sound_chips.c\n\truntime/src/rf5c68.c\n\truntime/src/ym3438.c\n\truntime/src/video.c\n\truntime/src/memory_census.c\n)\ntarget_include_directories(s32runtime PUBLIC runtime/include)\nif(UNIX AND NOT APPLE)\n\ttarget_link_libraries(s32runtime PUBLIC m)\nendif()\n\n# ---- ROM loader and board memories -----------------------------------------------------------------\nadd_library(ga2_data STATIC runtime/src/rom_set.c runtime/src/inflate.c)\ntarget_include_directories(ga2_data PUBLIC runtime/include PRIVATE runtime/src)\n\n# ---- reference tools (MAME cores; never linked into the game) --------------------------------------\noption(GA2_REFERENCE_TOOLS "Build the MAME-based reference tools" ON)\nif(GA2_REFERENCE_TOOLS)\n\tadd_library(s32video_reference STATIC tools/reference/video/s32video.cpp)\n\ttarget_include_directories(s32video_reference PUBLIC tools/reference/video PRIVATE runtime/include)\n\tif(MSVC)\n\t\ttarget_compile_options(s32video_reference PRIVATE /wd4244 /wd4267 /wd4100 /wd4146)\n\tendif()\n\n\tfind_package(Python3 COMPONENTS Interpreter REQUIRED)\n\tset(GA2_Z80_STEPS ${CMAKE_BINARY_DIR}/generated/cpu/z80/z80.hxx)\n\tadd_custom_command(OUTPUT ${GA2_Z80_STEPS}\n\t\tCOMMAND ${CMAKE_COMMAND} -E make_directory ${CMAKE_BINARY_DIR}/generated/cpu/z80\n\t\tCOMMAND Python3::Interpreter ${CMAKE_SOURCE_DIR}/tools/reference/mame/z80/z80make.py z80\n\t\t\t${CMAKE_SOURCE_DIR}/tools/reference/mame/z80/z80.lst ${GA2_Z80_STEPS}\n\t\tDEPENDS tools/reference/mame/z80/z80make.py tools/reference/mame/z80/z80.lst\n\t\tVERBATIM)\n\tadd_library(s32sound_reference STATIC\n\t\ttools/reference/sound/s32sound.cpp\n\t\ttools/reference/ymfm/ymfm_opn.cpp\n\t\ttools/reference/ymfm/ymfm_adpcm.cpp\n\t\ttools/reference/ymfm/ymfm_ssg.cpp\n\t\t${GA2_Z80_STEPS}\n\t)\n\ttarget_include_directories(s32sound_reference PUBLIC tools/reference/sound\n\t\tPRIVATE tools/reference/ymfm runtime/include ${CMAKE_BINARY_DIR}/generated)\n\tif(MSVC)\n\t\ttarget_compile_options(s32sound_reference PRIVATE /bigobj /wd4244 /wd4267 /wd4100 /wd4146 /wd4127)\n\tendif()\n\n\tadd_executable(s32ref\n\t\ttools/reference/s32ref.cpp\n\t\ttools/reference/mame/v60.cpp\n\t\ttools/reference/mame/v60d.cpp\n\t)\n\ttarget_include_directories(s32ref PRIVATE tools/reference/stub tools/reference/mame)\n\ttarget_link_libraries(s32ref PRIVATE s32runtime ga2_data s32video_reference s32sound_reference)\n\tif(MSVC)\n\t\ttarget_compile_options(s32ref PRIVATE /wd4646 /wd4244)\n\tendif()\nendif()\n\n# ---- translated V60 program (generated from the user\'s ROM; not in the source tree) -----------------\nfile(GLOB GA2_GENERATED CONFIGURE_DEPENDS ${CMAKE_SOURCE_DIR}/build/generated/*.c)\nfile(GLOB GA2_SOUND CONFIGURE_DEPENDS ${CMAKE_SOURCE_DIR}/src/sound/*.c)\nif(GA2_GENERATED)\n\tadd_library(ga2_program STATIC runtime/src/v60.c ${GA2_GENERATED})\n\ttarget_include_directories(ga2_program PUBLIC runtime/include build/generated)\n\ttarget_link_libraries(ga2_program PUBLIC s32runtime)\n\tif(MSVC)\n\t\ttarget_compile_options(ga2_program PRIVATE /bigobj)\n\tendif()\n\n\tif(GA2_SOUND)\n\t\tadd_library(ga2_sound STATIC runtime/src/sound_cpu.c ${GA2_SOUND})\n\t\ttarget_include_directories(ga2_sound PUBLIC runtime/include ${CMAKE_SOURCE_DIR}/src/sound)\n\t\ttarget_link_libraries(ga2_sound PUBLIC s32runtime)\n\tendif()\n\n\tadd_executable(ga2_headless ports/headless/main.c)\n\ttarget_link_libraries(ga2_headless PRIVATE ga2_program ga2_data)\n\tif(TARGET ga2_sound)\n\t\ttarget_link_libraries(ga2_headless PRIVATE ga2_sound)\n\t\ttarget_compile_definitions(ga2_headless PRIVATE GA2_SOUND=1)\n\tendif()\n\n\t# ---- window port --------------------------------------------------------------------------\n\tfind_package(PkgConfig QUIET)\n\tif(PkgConfig_FOUND)\n\t\tpkg_check_modules(SDL2 QUIET sdl2)\n\tendif()\n\tif(NOT SDL2_FOUND)\n\t\tfind_path(SDL2_INCLUDE_DIR SDL.h HINTS ENV SDL2_DIR PATH_SUFFIXES include/SDL2 include)\n\t\tfind_library(SDL2_LIBRARY NAMES SDL2 SDL2-static HINTS ENV SDL2_DIR PATH_SUFFIXES lib lib64)\n\t\tif(SDL2_INCLUDE_DIR AND SDL2_LIBRARY)\n\t\t\tset(SDL2_FOUND TRUE)\n\t\t\tset(SDL2_INCLUDE_DIRS ${SDL2_INCLUDE_DIR})\n\t\t\tset(SDL2_LIBRARIES ${SDL2_LIBRARY})\n\t\tendif()\n\tendif()\n\tif(SDL2_FOUND)\n\t\tadd_executable(GoldenAxe2 WIN32 ports/sdl2/main.c)\n\t\ttarget_link_libraries(GoldenAxe2 PRIVATE ga2_program ga2_data ${SDL2_LIBRARIES})\n\t\tif(TARGET ga2_sound)\n\t\t\ttarget_link_libraries(GoldenAxe2 PRIVATE ga2_sound)\n\t\t\ttarget_compile_definitions(GoldenAxe2 PRIVATE GA2_SOUND=1)\n\t\tendif()\n\t\ttarget_include_directories(GoldenAxe2 PRIVATE ${SDL2_INCLUDE_DIRS})\n\t\tif(TARGET SDL2::SDL2)\n\t\t\ttarget_link_libraries(GoldenAxe2 PRIVATE SDL2::SDL2)\n\t\tendif()\n\t\tif(WIN32 AND NOT MSVC)\n\t\t\ttarget_link_options(GoldenAxe2 PRIVATE -mwindows)\n\t\t\tif(SDL2_LIBRARY)\n\t\t\t\tadd_custom_command(TARGET GoldenAxe2 POST_BUILD\n\t\t\t\t\tCOMMAND ${CMAKE_COMMAND} -E copy_if_different ${SDL2_LIBRARY} $<TARGET_FILE_DIR:GoldenAxe2>)\n\t\t\tendif()\n\t\tendif()\n\t\tif(WIN32)\n\t\t\tadd_custom_command(TARGET GoldenAxe2 POST_BUILD\n\t\t\t\tCOMMAND ${CMAKE_COMMAND} -E copy_if_different ${CMAKE_SOURCE_DIR}/rom/ga2.zip $<TARGET_FILE_DIR:GoldenAxe2>/ga2.zip)\n\t\tendif()\n\telse()\n\t\tmessage(STATUS "No SDL2: only ga2_headless will be built")\n\tendif()\nelse()\n\tmessage(STATUS "No translated program in build/generated: run tools/recompile.py first")\nendif()\n'

def main():
    target = Path(__file__).resolve().parent.parent / "CMakeLists.txt"
    target.write_text(CONTENT, encoding="utf-8")
    print(f"wrote {target}")


if __name__ == "__main__":
    main()
